INSERT INTO RES_ADDED
(
    ID
    ,PRICEREQNO
    ,APPNO
    ,APPNAME
    ,PROJECTNAME
    ,PROJECTNO
    ,EXPECTEDONLINETIME
    ,AMOUNT
    ,STATUS
    ,CREATOR
    ,CREATETIME
    ,CREATORNAME
    ,SOURCETYPE
    ,BUSIDEPTNAME
    ,TECHDEPTNAME
    ,SYSOPERLEVEL
    ,ISFUNDTRANS
    ,CIID
    ,BUSIDEPTID
    ,TECHDEPTID
    ,PROCESSINSTID
    ,DOCMID
    ,RENEWPROCESSNO
)
VALUES
(
    #{id}
    ,#{priceReqNo}
    ,#{appNo}
    ,#{appName}
    ,#{projectName}
    ,#{projectNo}
    ,TO_DATE(#{expectedOnlineTime},'YYYY-MM-DD')
    ,#{amount}
    ,#{status}
    ,#{creator}
    ,TO_DATE(#{createTime},'YYYY-MM-DD HH24:MI:SS')
    ,#{creatorName}
    ,#{sourceType}
    ,#{busiDeptName}
    ,#{techDeptName}
    ,#{sysOperLevel}
    ,#{isFundTrans}
    ,#{ciid}
    ,#{busiDeptId}
    ,#{techDeptId}
    ,#{processInstID}
    ,#{docmId}
    ,#{reNewProcessNo}
)

