mapper.update:
UPDATE RES_ADDED SET STATUS=#{status}
,BUDGETNO=#{budgetNo}
,EVALUATENO=#{evaluateNo}
,EVALUATEURL=#{evaluateUrl}
,SYSDEALUSER=#{sysDealUser}
WHERE ID=#{id}

mapper.select:
SELECT

FROM RES_ADDED a
WHERE a.ID =#{id}

SELECT * FROM RES_CONFIG_COMBO t
WHERE t.DEVOPSLEVEL =#{sysOperLevel}
AND t.ISRELATEFUND = #{isFundTrans}
AND t.STATUS = 2

SELECT CASE WHEN m.CATEGORY = '2' THEN '【' || n.DICTNAME || '】' || m.APPLYSCENE WHEN m.CATEGORY = '5' THEN m.APPLYSCENE ELSE m.DESCRIBE END AS DESCRIPTION FROM RES_CONFIG_COMBO m LEFT JOIN EOS_DICT_ENTRY n ON m.SUBCATEGORY = n.DICTID WHERE n.DICTTYPEID = 'RES_SUBCATEGORY' AND m.ISCANCEL = 1 AND m.ID = #{id}
UNION
SELECT m.SOFTNAME || ' ' || m.SOFTVERSION AS DESCRIPTION FROM RES_CONFIG_SOFT m WHERE m.ISCANCEL = 1 AND m.ID = #{id}
UNION
SELECT n.DICTNAME || '(' || m.DESCRIBE || ')' AS DESCRIPTION FROM RES_CONFIG_VM m LEFT JOIN EOS_DICT_ENTRY n ON m.TYPE = n.DICTID WHERE n.DICTTYPEID = 'RES_VM_TYPE' AND m.ISCANCEL =1 AND m.ID = #{id}
